package main
import("fmt";"strings";"github.com/grafov/m3u8")
func main(){src:="#EXTM3U\n#EXT-X-VERSION:9\n#EXT-X-TARGETDURATION:2\n#EXT-X-MEDIA-SEQUENCE:77\n#EXT-X-PART-INF:PART-TARGET=0.5\n#EXT-X-PART:DURATION=0.5,URI=\"77.0.m4s\",INDEPENDENT=YES\n#EXTINF:2,\n77.m4s\n#EXT-X-PART:DURATION=0.5,URI=\"78.0.m4s\"\n#EXT-X-PRELOAD-HINT:TYPE=PART,URI=\"78.1.m4s\"\n";p,err:=m3u8.NewMediaPlaylist(3,5);if err!=nil{panic(err)};if err=p.DecodeFrom(strings.NewReader(src),true);err!=nil{panic(err)};out:=p.Encode().String();if p.Count()!=1||!strings.Contains(out,"77.m4s"){panic("complete segment baseline failed")};fmt.Printf("complete_segments=%d media_sequence=%d\n",p.Count(),p.SeqNo);fmt.Printf("part_tags_preserved=%v preload_preserved=%v\n",strings.Contains(out,"#EXT-X-PART:"),strings.Contains(out,"#EXT-X-PRELOAD-HINT:"));if strings.Contains(out,"#EXT-X-PART:"){panic("unexpected starting capability")}}
